function notice(title,body='',danger=false){if(!entered)return;$('noticeTitle').textContent=title;$('noticeBody').textContent=body;$('noticeEyebrow').textContent=danger?'FLIGHT ALERT':'FLIGHT EVENT';$('missionNotice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('missionNotice').hidden=true,4500)}
