function requestAbort(){const s=sim.state;if(['ABORTED','COMPLETE','FLIGHT_ABORT'].includes(s.phase)){toast('Mission is already ended or aborting.');return}confirm('Abort mission?',s.time<0?'Stop the countdown, shut down the engines and safe the vehicle. A restart requires a fresh mission.':'Command immediate engine shutdown. The vehicle will follow a ballistic trajectory. This is not a crew escape command.','CONFIRM ABORT',()=>{act(sim.abort('Flight director commanded abort.'));audio.say('Abort. Abort. Abort.');audio.tone(210,.7,.1)})}
