$$('[data-rig]').forEach(b=>b.onclick=()=>setRig(b.dataset.rig));$('trackBtn').onclick=()=>{scene?.setCamera({tracking:!scene.tracking});$('trackBtn').classList.toggle('active',!!scene?.tracking)};$('zoomIn').onclick=()=>scene?.setCamera({zoom:scene.zoom*.82});$('zoomOut').onclick=()=>scene?.setCamera({zoom:scene.zoom*1.22});
function setMultiview(on){multiview=!!on;if(on){setRig('chase');scene?.setCamera({zoom:1});}scene?.setMultiview(multiview);$('game').classList.toggle('split-screen',multiview);$('splitOverlays').hidden=!multiview;$('splitBtn').classList.toggle('active',multiview);$('splitBtn').setAttribute('aria-pressed',String(multiview));$('splitBtn').setAttribute('aria-label',multiview?'Disable split screen':'Enable split screen');updateSplit();}
$('splitBtn').onclick=()=>setMultiview(!multiview);$$('[data-focus]').forEach(b=>b.onclick=()=>{setTarget(b.dataset.focus);if(rig==='port'||rig==='free')setRig('chase');updateSplit();audio.chime()});
function updateSplit(){if(!multiview||!scene)return;const s=sim.state;for(const rect of scene.getViewports()){const el=$$('[data-pane]').find(e=>e.dataset.pane===rect.kind);if(!el)continue;Object.assign(el.style,{left:rect.x*100+'%',top:rect.y*100+'%',width:rect.width*100+'%',height:rect.height*100+'%'});el.classList.toggle('primary',rect.primary);const kind=rect.kind,c=kind==='capsule'?s.capsule:kind==='booster'?s.booster:s,attached=kind==='capsule'?!c.active:kind==='booster'?!c.separated:false;let phase=kind==='ship'&&s.outcome?.includes('VEHICLE LOST')?'IMPACT':attached?'ATTACHED':kind==='ship'&&s.recovery.caught?'TOWER CAPTURED':c.phase.replaceAll('_',' ');el.querySelector('.pane-phase').textContent=phase;el.querySelector('.pane-alt').textContent=((attached?s.altitude:c.altitude)/1000).toFixed(2)+' km';el.querySelector('.pane-speed').textContent=Math.round(attached?s.verticalVelocity:c.verticalVelocity)+' m/s';el.querySelector('.pane-thrust').textContent=attached?'AWAITING SEPARATION':Math.round((c.thrust||0)/1000).toLocaleString()+' kN';}}
function updatePort(dt,active){const port=scene?.spaceport;if(!port)return;trafficStamp+=dt;portRadioTime+=active?dt:0;if(trafficStamp>1){trafficStamp=0;const rows=port.getTraffic();$('trafficRows').replaceChildren(...rows.map(t=>{const li=document.createElement('li'),b=document.createElement('b'),span=document.createElement('span'),small=document.createElement('small');b.textContent=t.name||t.callsign||t.id;span.textContent=t.phase||t.status;small.textContent=(t.altitude!=null?(t.altitude/1000).toFixed(1)+' km · ':'')+(t.eta!=null?Math.ceil(t.eta)+'s':'');li.append(b,span,small);return li}));}const events=port.drainEvents?.()||[];if(entered&&active&&portRadioTime>24&&events.length){const e=events[events.length-1];audio.say(e.message||e.text||`${e.name}, ${e.phase==='ASCENT'?'liftoff confirmed':e.phase==='RETURN'?'inbound to Starbase':e.phase==='LANDING'?'landing burn is active':e.phase==='CAPTURED'?'tower capture confirmed':e.phase==='READY'?'ready for departure':e.phase==='TRANSFER'?'transfer corridor clear':'turnaround in progress'}. ${e.route||'Spaceport traffic remains nominal'}.`,{priority:0,key:'traffic-'+(e.id||e.name||Math.floor(portRadioTime)),kind:'SPACEPORT CONTROL'});portRadioTime=0;}}
