$$('[data-config]').forEach(el=>el.addEventListener(el.type==='range'?'input':'change',()=>{const value=el.type==='checkbox'?el.checked:Number(el.value)*Number(el.dataset.scale||1);act(sim.configure(el.dataset.config,value),true)}));
