function hold(){act(sim.state.phase==='HOLD'?sim.resume():sim.hold())}
$('holdBtn').onclick=hold;$('abortBtn').onclick=requestAbort;$('consoleAbort').onclick=requestAbort;
$('launchBtn').onclick=()=>{const s=sim.state;if(['COMPLETE','ABORTED'].includes(s.phase)){prepareReport();reportShown=s.capsule.active?['LANDED','IMPACT'].includes(s.capsule.phase):true;showDialog('reportDialog');return}if(s.phase==='HOLD'){act(sim.resume());return}if(['COUNTDOWN','IGNITION'].includes(s.phase)){hold();return}if(s.time>=0){closeConsole();return}if(act(sim.startCountdown())){closeConsole();notice('The count is running.','Launch authority confirmed. All stations monitor.');audio.say('All stations go. Proceeding with terminal count.')}};
function enter(mode){entered=true;if(!audioStarted){audioStarted=true;audio.toggle();syncSound()};paused=false;menuPaused=false;$('titleScreen').hidden=true;$('hud').hidden=false;$('pauseMenu').hidden=true;closeConsole();setView(mode==='mission'?'mission':'pad');if(mode==='quick'||mode==='split'){resetSession();autoConfig(true);allGo(true);sim.startCountdown();sim.tick(90);setRig('tripod');notice('T minus 30 seconds.','Quick launch · all systems and stations are GO.')}else if(mode==='explore'){setRig('port');toast('Spaceport overview · live departures and arrivals. Choose FREE to explore.')}if(mode==='split')setMultiview(true);audio.say(mode==='explore'?'Welcome to Starbase. Five launch complexes are active. Watch the traffic board for arrivals and departures.':'Flight director, you have the mission. Recovery systems are ready. Monitor the vehicle and keep the escape corridor clear.',{priority:1,key:'welcome',kind:'FLIGHT DIRECTOR'});renderUI()}
$('enterMission').onclick=()=>enter('mission');$('quickLaunch').onclick=()=>enter('quick');$('exploreBtn').onclick=()=>enter('explore');$('splitLaunch').onclick=()=>enter('split');
