function menu(open){menuPaused=open;$('pauseMenu').hidden=!open;$('hud').inert=open;$('console').inert=open;keys.clear();if(open){audio.cancel();$('resumeBtn').focus()}else if(entered)$('menuBtn').focus()}
$('menuBtn').onclick=()=>menu(true);$('resumeBtn').onclick=()=>menu(false);$('pauseBtn').onclick=pause;
function resetSession(){lastIncident=0;failureReportDelay=0;pendingBlastAudio=[];scene?.resetFailures();audio.resetExplosions?.();setMultiview(false);$('game').classList.remove('port-view');$('trafficBoard').hidden=true;sim.reset();rate=1;paused=false;reportShown=false;lastEvent=0;lastSecond=-120;lastEngineStage=0;keys.clear();clearTimeout(noticeTimer);$('missionNotice').hidden=true;audio.cancel();rig='tripod';cameraTarget='ship';$('cameraTarget').value='ship';scene?.setCamera({spaceport:false,free:false,cinematic:false,engineView:false,target:'ship',zoom:1,night:false,tracking:true});$$('[data-rig]').forEach(b=>b.classList.toggle('active',b.dataset.rig==='tripod'));$('trackBtn').classList.add('active');$('nightToggle').checked=false}
