$$('[data-rate]').forEach(b=>b.onclick=()=>{rate=Number(b.dataset.rate);renderUI()});
$('qualitySelect').value='medium';$('qualitySelect').onchange=()=>{scene?.setQuality($('qualitySelect').value);toast('Graphics quality: '+$('qualitySelect').value)};
