const audio=new FlightAudio({getContext:()=>({view,cameraTarget,rate}),onCaption:(text,meta={})=>{clearTimeout(captionTimer);$('radioCaption').hidden=!text||!entered;$('radioSpeaker').textContent=(meta.kind||'MISSION RADIO').replaceAll('-',' ').toUpperCase();$('radioText').textContent=text||'';if(text)captionTimer=setTimeout(()=>$('radioCaption').hidden=true,Math.min(9000,Math.max(3600,text.length*45)));}});
