function prepareReport(){const s=sim.state,cap=s.capsule,escape=['LANDED','IMPACT'].includes(cap.phase);$('reportTitle').textContent=cap.phase==='IMPACT'?'Capsule impact.':escape?'Escape exercise complete.':s.outcome.includes('LOST')?'Flight ended.':'Mission record.';$('reportOutcome').style.color=/IMPACT|LOST/.test(s.outcome)?'#e5a08e':'';$('reportOutcome').textContent=s.outcome||s.abortReason||phaseNames[s.phase];const stats=s.recovery?.caught&&!cap.active?[['PEAK ALTITUDE',(s.maxAltitude/1000).toFixed(1)+' km'],['BOOSTER LANDING',s.booster.phase==='LANDED'?s.booster.touchdownSpeed.toFixed(2)+' m/s':s.booster.phase],['SHIP CAPTURE',s.recovery.touchdownSpeed.toFixed(2)+' m/s'],['RECOVERY SITE','STARBASE']]:escape?[['CAPSULE PEAK ALT',(cap.maxAltitude/1000).toFixed(2)+' km'],['PEAK SPEED',cap.maxVelocity.toFixed(0)+' m/s'],['TOUCHDOWN',cap.touchdownSpeed.toFixed(1)+' m/s'],['PARACHUTE',cap.parachute?'DEPLOYED':'STOWED']]:[['PEAK ALTITUDE',(s.maxAltitude/1000).toFixed(1)+' km'],['PEAK VELOCITY',(s.maxVelocity/1000).toFixed(2)+' km/s'],['MAX Q',(s.maxQ/1000).toFixed(1)+' kPa'],['DOWNRANGE',(s.downrange/1000).toFixed(0)+' km']];$('reportStats').innerHTML=stats.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}
function exportFlight(){const s=sim.state;const data={application:'Starship Flight Director',version:'5.0',exportedAt:new Date().toISOString(),model:'Illustrative 2D variable-mass ascent and guided return; fictional capsule and upper-stage tower catch.',configuration:s.config,systems:s.systems,votes:s.votes,phase:s.phase,outcome:s.outcome,missionTime:s.time,peakAltitude:s.maxAltitude,peakVelocity:s.maxVelocity,maximumDynamicPressure:s.maxQ,downrange:s.downrange,capsule:s.capsule,booster:s.booster,recovery:s.recovery,milestones:s.milestones,trajectory:s.trajectory,incidents:s.incidents,events:s.events};const json=JSON.stringify(data,null,2);$('exportText').value=json;if(exportURL)URL.revokeObjectURL(exportURL);exportURL=URL.createObjectURL(new Blob([json],{type:'application/json'}));$('downloadJSON').href=exportURL;$('downloadJSON').download='starship-flight-'+Date.now()+'.json';$('reportDialog').close();showDialog('exportDialog')}
