function engineMap(s){const booster=cameraTarget==='booster'||!s.separated,stage=booster?1:2,status=booster?s.engineStatus.booster:s.engineStatus.ship;if(lastEngineStage!==stage){lastEngineStage=stage;$('engineMap').replaceChildren();const positions=[];if(booster){for(let i=0;i<3;i++)positions.push([50+8*Math.cos(i*Math.PI*2/3),50+8*Math.sin(i*Math.PI*2/3)]);for(let i=0;i<10;i++)positions.push([50+23*Math.cos(i*Math.PI/5),50+23*Math.sin(i*Math.PI/5)]);for(let i=0;i<20;i++)positions.push([50+39*Math.cos(i*Math.PI/10),50+39*Math.sin(i*Math.PI/10)])}else for(let i=0;i<6;i++)positions.push([50+28*Math.cos(i*Math.PI/3),50+28*Math.sin(i*Math.PI/3)]);positions.forEach(([x,y],i)=>{const e=document.createElement('i');e.className='engine-dot';e.style.left=x+'%';e.style.top=y+'%';e.title='Engine '+(i+1);$('engineMap').append(e)})}[...$('engineMap').children].forEach((e,i)=>{e.classList.toggle('firing',status[i]==='RUNNING');e.classList.toggle('offline',status[i]==='OFFLINE')})}
