const propBody=cameraTarget==='booster'&&s.booster.separated?s.booster:s;$('thrust').innerHTML=(propBody.thrust/1e6).toFixed(1)+' <small>MN</small>';$('maxQ').innerHTML=((propBody.dynamicPressure||0)/1000).toFixed(1)+' <small>kPa</small>';$('downrange').innerHTML=(propBody.downrange/1000).toFixed(1)+' <small>km</small>';$('mach').textContent='MACH '+(propBody.mach||0).toFixed(2);$('engineCount').textContent=(cameraTarget==='booster'&&s.booster.separated?s.booster.activeEngines:s.activeEngines)+' / '+(cameraTarget==='booster'?33:s.phase==='HOT_STAGING'?39:s.stage===1?33:6);engineMap(s);recoveryUI(s);
