function drawChart(){const c=$('flightChart'),r=c.getBoundingClientRect();if(!r.width||!r.height)return;const dpr=Math.min(devicePixelRatio||1,2);c.width=r.width*dpr;c.height=r.height*dpr;const g=c.getContext('2d');g.scale(dpr,dpr);const w=r.width,h=r.height,left=28,top=10,bottom=21,pw=w-left-8,ph=h-top-bottom,points=sim.state.trajectory,maxAlt=Math.max(20,...points.map(p=>p.altitude/1000)),maxVel=Math.max(1,...points.map(p=>p.velocity/1000)),maxT=Math.max(120,sim.state.time);g.font='8px "IBM Plex Mono",monospace';g.strokeStyle='#7591a329';g.fillStyle='#8a9da7';for(let i=0;i<=3;i++){const y=top+ph*(1-i/3);g.beginPath();g.moveTo(left,y);g.lineTo(w,y);g.stroke();g.fillText(Math.round(maxAlt*i/3),0,y+3);g.fillText(Math.round(maxT*i/3)+'s',left+pw*i/3-8,h-3)}for(const [key,max,color] of [['altitude',maxAlt,'#9bd7c9'],['velocity',maxVel,'#d7ba8d']]){g.beginPath();points.forEach((p,i)=>{const x=left+pw*Math.max(0,p.time)/maxT,y=top+ph*(1-p[key]/1000/max);i?g.lineTo(x,y):g.moveTo(x,y)});g.strokeStyle=color;g.lineWidth=1.5;g.stroke()}if(!points.length){g.fillStyle='#81949f';g.fillText('AWAITING LIFTOFF',left+15,ph*.55)}}
function interact(hit){const target=hit||scene?.getInteractable();if(!target){openConsole();return}audio.chime();switch(target.action){case'abort':requestAbort();break;case'eject':requestEject();break;case'parachute':deployChutes();break;case'return':returnShip();break;case'hold':hold();break;case'autopilot':act(sim.configure('autopilot',!sim.state.config.autopilot));break;case'throttle':openConsole('vehicle');break;case'poll':openConsole('checklist');break;default:openConsole()}}
function isEditing(e){return /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable||document.querySelector('dialog[open]')}
document.addEventListener('keydown',e=>{
 if(isEditing(e))return;
 const key=e.key.toLowerCase();
 if(e.key==='Escape'&&entered&&!e.repeat){e.preventDefault();if(menuPaused)menu(false);else if(!$('console').hidden)closeConsole();else menu(true);return}
 // Let Space activate a focused button through the browser's normal keyboard behavior.
 if(e.code==='Space'&&e.target.closest?.('button,a[href],[role="button"]'))return;
 // Only the pause menu's own buttons are actionable while it covers the flight.
 if(!entered||menuPaused)return;
 if(view==='pad'&&rig==='free'&&$('console').hidden&&['w','a','s','d','q','r','shift'].includes(key)){keys.add(key);e.preventDefault();return}
 if(e.repeat)return;
 if(['1','2','3'].includes(key)){e.preventDefault();setView({1:'mission',2:'cockpit',3:'pad'}[key])}
 else if(e.code==='Space'){e.preventDefault();pause()}
 else if(key==='c'){e.preventDefault();$('console').hidden?openConsole():closeConsole()}
 else if(key==='h'){e.preventDefault();hold()}
 else if(key==='e'){e.preventDefault();interact()}
 else if(key==='p'){e.preventDefault();deployChutes()}
 else if(key==='s'){e.preventDefault();setMultiview(!multiview)}else if(key==='m')toggleSound();else if(key==='f')fullscreen()
});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
let loadFailed=[];THREE.DefaultLoadingManager.onProgress=(url,done,total)=>{$('loadProgress').style.width=(done/total*100)+'%';$('loadDetail').textContent=`Loading environment · ${done} / ${total}`;if(bootReady)$('assetStatus').textContent=`READY TO PLAY · TEXTURES ${done}/${total}`};THREE.DefaultLoadingManager.onError=url=>loadFailed.push(url);THREE.DefaultLoadingManager.onLoad=()=>{if(loadFailed.length)toast('Some visual assets could not load. Reload with the complete asset folder.',true);$('loading').hidden=true;$('assetStatus').textContent='READY · OPTIMIZED ASSETS LOADED'};
function handleIncidents(active,dt){
 if(!entered||!scene)return;
 if(active)failureReportDelay=Math.max(0,failureReportDelay-dt);
 for(const incident of sim.state.incidents||[]){
  if(incident.id<=lastIncident)continue;lastIncident=incident.id;scene.triggerFailure(incident);pendingBlastAudio.push({incident,remaining:1});
  const major=incident.kind!=='engine-failure',name=incident.attached?'VEHICLE STACK':incident.body==='booster'?'SUPER HEAVY':incident.body==='capsule'?'CREW CAPSULE':'STARSHIP';
  if(major){failureReportDelay=10;reportShown=false;}
  if(major&&incident.kind==='impact'&&view==='cockpit'&&(incident.body==='capsule'||incident.body==='ship'&&!sim.state.capsule.active)){setTarget(incident.body);setRig('chase');}
  const title=name+' · '+(incident.kind==='impact'?'SURFACE IMPACT':incident.kind==='rupture'?'VEHICLE RUPTURE':'ENGINE FAILURE');
  notice(title,'Tracking debris and fire at the failure location.',true);
  audio.say(incident.kind==='impact'?name+'. Impact confirmed. Vehicle lost.':incident.kind==='rupture'?'Major vehicle failure. Fire and debris detected.':'Uncontained engine failure. Monitor vehicle response.',{key:'incident-'+incident.id,kind:'FLIGHT SAFETY',priority:3});
 }
 if(active&&pendingBlastAudio.length){
  if(audio.enabled)audio.update(sim.state,true);
  // Muted effects are consumed. Only a brief AudioContext resume can defer a cue;
  // raising a volume slider must never replay a blast from an earlier moment.
  pendingBlastAudio=pendingBlastAudio.filter(item=>{
   item.remaining-=dt;
   if(!audio.enabled||audio.settings.master===0||audio.settings.effects===0||item.remaining<=0)return false;
   return !audio.explosion?.(item.incident);
  });
 }
}
function frame(now){const dt=Math.min((now-(lastNow||now))/1000,.1);lastNow=now;const active=entered&&!paused&&!menuPaused&&!document.hidden;try{if(active)sim.tick(dt*rate);handleIncidents(active,dt);scene?.setMovement({forward:(keys.has('w')?1:0)-(keys.has('s')?1:0),right:(keys.has('d')?1:0)-(keys.has('a')?1:0),up:(keys.has('r')?1:0)-(keys.has('q')?1:0),fast:keys.has('shift')});if(!document.hidden)scene?.update(sim.state,dt,!entered||active);updatePort(dt,!entered||active);uiTime+=dt;chartTime+=dt;fpsTime+=dt;frames++;if(uiTime>.1){renderUI();updateSplit();audio.update(sim.state,active);const target=entered&&$('console').hidden&&!menuPaused?scene?.getInteractable():null;$('interaction').hidden=!target;$('interactionText').textContent=target?.label||'';const sec=Math.ceil(sim.state.time);if(sec!==lastSecond&&sec<0&&sec>=-10&&active&&sim.state.phase==='COUNTDOWN'){audio.tone(820,.08,.055);if(rate===1)audio.say(String(-sec),{priority:2,key:'count-'+sec,kind:'COUNTDOWN'})}lastSecond=sec;uiTime=0}if(chartTime>.5){if(!$('panel-telemetry').hidden&&!$('console').hidden)drawChart();chartTime=0}if(fpsTime>1){$('fpsLabel').textContent=Math.round(frames/fpsTime)+' FPS';const ps=scene?.getPerformanceStats?.();if(ps)$('performanceReadout').textContent=Math.round(frames/fpsTime)+' FPS · '+(ps.views||1)+' VIEW(S) · '+Number(ps.pixelRatio||ps.dpr||1).toFixed(2)+'× RESOLUTION · LOCAL GPU';fpsTime=0;frames=0}}catch(err){paused=true;console.error(err);toast('Simulation paused after a rendering error. Reload the page.',true)}requestAnimationFrame(frame)}
window.addEventListener('resize',()=>{scene?.resize();updateSplit();drawChart()});document.addEventListener('visibilitychange',()=>{lastNow=performance.now();keys.clear();if(document.hidden){audio.update(sim.state,false);audio.cancel()}});
