selectPanel('checklist');renderUI();requestAnimationFrame(()=>{try{scene=new StarbaseScene($('world'),{mode:'pad',quality:$('qualitySelect').value});window.starbaseScene=scene;scene.cameraShock=$('shockToggle').checked;scene.setCamera({zoom:1.05});scene.update(sim.state,0);setView('pad');bootReady=true;$('loading').hidden=true;$('assetStatus').textContent='READY TO PLAY · TEXTURES STREAMING';requestAnimationFrame(frame)}catch(err){console.error(err);$('loadDetail').textContent='WebGL could not start. Enable hardware acceleration and reload.';$('loadProgress').style.width='0%'}});
